#!/usr/bin/env python3
"""Read attendees.csv and write attendees_clean.csv with duplicate emails removed."""
import csv

INPUT = "attendees.csv"
OUTPUT = "attendees_clean.csv"


def main():
    with open(INPUT, "r", encoding="utf-8", newline="") as infile:
        reader = csv.reader(infile)
        try:
            header = next(reader)
        except StopIteration:
            # Empty input: still write an empty output file.
            with open(OUTPUT, "w", encoding="utf-8", newline="") as outfile:
                pass
            return

        try:
            email_index = header.index("email")
        except ValueError:
            raise ValueError("attendees.csv does not have an email column")

        seen_emails = set()
        rows = [header]

        for row in reader:
            if len(row) <= email_index:
                email = ""
            else:
                email = row[email_index]
            if email in seen_emails:
                continue
            seen_emails.add(email)
            rows.append(row)

    with open(OUTPUT, "w", encoding="utf-8", newline="") as outfile:
        writer = csv.writer(outfile)
        writer.writerows(rows)


if __name__ == "__main__":
    main()
